// Excerpt from a Special Move script's SkillFunc(_success): pick one of 3
// animation variants at random to vary the technique's presentation.
local variantIndex = CMND_RANDOM(3);
if (variantIndex == 0)
{
	SetupNum(1, 0, 0, 1, 2);
	SetupEnable(1, "gol", 0);
}
else if (variantIndex == 1)
{
	SetupNum(1, 0, 0, 1, 2);
	SetupMotion(1, "01a");
	SetupEnable(1, "gol", 0);
}
else
{
	SetupNum(1, 0, 0, 1, 2);
	SetupMotion(1, "01b");
}
